steps.script:
local out = {}
local threads = steps.list_threads.result.threads or {}
for _, thread in ipairs(threads) do
  for _, msg in ipairs(thread.messages or {}) do
    table.insert(out, {
      gmail_id = msg.id,
      thread_id = thread.id,
      thread_snippet = thread.snippet,
      from_email = msg.from,
      subject = msg.subject,
      date = msg.date,
    })
  end
end
return {
  messages = out,
  next_page_token = steps.list_threads.result.next_page_token,
}
